<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';const props=defineProps({competitions:Array});const form=useForm({name:'',type:'head_to_head',starts_gameweek:1});const create=()=>form.post('/competitions',{onSuccess:()=>form.reset('name')});const labels={points:'Points race',head_to_head:'Head to head',survivor:'Survivor'};</script><template><Head title="Competitions"/><AppLayout><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="label">Beyond the main table</p><h1 class="mt-2 text-4xl font-black">Cups & side quests.</h1><p class="mt-2 text-[#718078]">Create new ways to win—or new ways to get cooked.</p></div><span class="rounded-full bg-[#f4d35e] px-4 py-2 text-xs font-black text-[#17241d]">All 6 managers included</span></div><div class="mt-8 grid gap-7 lg:grid-cols-[1.5fr_.8fr]"><section><div v-if="competitions.length" class="grid gap-5 sm:grid-cols-2"><Link v-for="c in competitions" :href="`/competitions/${c.id}`" class="card group p-6 hover:-translate-y-1"><div class="flex justify-between"><span class="rounded-full bg-[#e8eee8] px-3 py-1 text-[10px] font-black uppercase tracking-wider dark:bg-[#1a3026]">{{labels[c.type]}}</span><span>↗</span></div><h2 class="mt-6 text-2xl font-black">{{c.name}}</h2><p class="mt-1 text-sm text-[#718078]">From GW{{c.starts_gameweek}} · {{c.members.length}} managers</p><div class="mt-6 border-t border-black/5 pt-4 dark:border-white/10"><template v-if="c.summary.mode==='survivor'"><b>{{c.summary.survivors.length}} still standing</b><span class="block text-xs text-[#718078]">{{c.summary.eliminations.length}} eliminated</span></template><template v-else><b>{{c.summary.table[0]?.manager||'Awaiting scores'}}</b><span class="block text-xs text-[#718078]">Current leader</span></template></div></Link></div><div v-else class="card p-10 text-center"><span class="text-4xl">🏆</span><h2 class="mt-4 text-xl font-black">Create the first side competition</h2><p class="mt-2 text-sm text-[#718078]">The main league stays untouched.</p></div></section><aside class="card h-fit p-6"><span class="label">New competition</span><h2 class="mt-2 text-xl font-black">Start something.</h2><form @submit.prevent="create" class="mt-5 space-y-4"><label class="block"><span class="label">Name</span><input v-model="form.name" class="field mt-1" placeholder="Mandem Survival Series"></label><label class="block"><span class="label">Format</span><select v-model="form.type" class="field mt-1"><option value="head_to_head">Head-to-head league</option><option value="points">Points race</option><option value="survivor">Survivor</option></select></label><label class="block"><span class="label">Starting gameweek</span><input v-model="form.starts_gameweek" type="number" min="1" max="38" class="field mt-1"></label><p v-if="Object.keys(form.errors).length" class="text-sm text-red-500">{{Object.values(form.errors)[0]}}</p><button class="btn-primary w-full">Create competition →</button></form><div class="mt-5 space-y-2 border-t border-black/5 pt-5 text-xs leading-5 text-[#718078] dark:border-white/10"><p><b>Head to head:</b> 3 points for a weekly win.</p><p><b>Points race:</b> most points from the selected GW.</p><p><b>Survivor:</b> lowest scorer is eliminated weekly.</p></div></aside></div></AppLayout></template>
